composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    depends_on:
      - {{serviceName}}-db
      - {{serviceName}}-redis
    environment:
      TZ: {{env.TZ}}
      USERMAP_UID: {{env.USERMAP_UID}}
      USERMAP_GID: {{env.USERMAP_GID}}
      PAPERLESS_REDIS: {{env.PAPERLESS_REDIS}}
      PAPERLESS_DBHOST: {{serviceName}}-db
      PAPERLESS_DBNAME: {{env.PAPERLESS_DBNAME}}
      PAPERLESS_DBUSER: {{env.PAPERLESS_DBUSER}}
      PAPERLESS_DBPASS: {{env.PAPERLESS_DBPASS}}
      PAPERLESS_SECRET_KEY: {{env.PAPERLESS_SECRET_KEY}}
    volumes:
      - {{appDataPath}}/data:/usr/src/paperless/data
      - {{appDataPath}}/media:/usr/src/paperless/media
      - {{appDataPath}}/consume:/usr/src/paperless/consume
      - {{appDataPath}}/export:/usr/src/paperless/export
  {{serviceName}}-db:
    image: postgres:16-alpine
    container_name: {{containerName}}-db
    restart: unless-stopped
    environment:
      POSTGRES_DB: {{env.PAPERLESS_DBNAME}}
      POSTGRES_USER: {{env.PAPERLESS_DBUSER}}
      POSTGRES_PASSWORD: {{env.PAPERLESS_DBPASS}}
    volumes:
      - {{appDataPath}}/postgres:/var/lib/postgresql/data
  {{serviceName}}-redis:
    image: redis:7-alpine
    container_name: {{containerName}}-redis
    restart: unless-stopped
    volumes:
      - {{appDataPath}}/redis:/data
